-- Демонстрационные данные ПС «Страховой сервис» (сгенерированы tools/gen_demo_data.py)
-- Пароли: admin/admin123, агенты — agent123, клиенты — client123
\connect insurance
BEGIN;
COMMIT;
SELECT setval(pg_get_serial_sequence('users', 'id'), (SELECT max(id) FROM users));
SELECT setval(pg_get_serial_sequence('clients', 'id'), (SELECT max(id) FROM clients));
SELECT setval(pg_get_serial_sequence('agents', 'id'), (SELECT max(id) FROM agents));
SELECT setval(pg_get_serial_sequence('insurance_types', 'id'), (SELECT max(id) FROM insurance_types));
SELECT setval(pg_get_serial_sequence('applications', 'id'), (SELECT max(id) FROM applications));
SELECT setval(pg_get_serial_sequence('policies', 'id'), (SELECT max(id) FROM policies));
SELECT setval(pg_get_serial_sequence('claims', 'id'), (SELECT max(id) FROM claims));
